  @WellFounded.{u_1 + 1} α r →
    ∀ (s : Set.{u_1} α),
      @Set.Nonempty.{u_1} α s →
        @Exists.{u_1 + 1} α fun a =>
          And (@Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s a)
            (∀ (x : α), @Membership.mem.{u_1, u_1} α (Set.{u_1} α) (@Set.instMembership.{u_1} α) s x → Not (r x a))
